+        let projection = ProjectionExprs::new([]);
+        let mut build_count = 0;
+
+        for physical_schema in [&first_schema, &second_schema, &first_schema] {
+            cache
+                .get_or_insert_with(
+                    &logical_schema,
+                    physical_schema,
+                    &projection,
+                    None,
+                    || {
+                        build_count += 1;
+                        Ok(setup())
+                    },
+                )
+                .unwrap();
+        }
+
+        assert_eq!(cache.len(), 1);
+        assert_eq!(build_count, 3);
+    }
+}
